import postgres from "postgres";
const env=Bun.env;
if(!env.DATABASE_URL)throw new Error("DATABASE_URL is required");
const sql=postgres(env.DATABASE_URL,{max:8,idle_timeout:20,connect_timeout:10});
const gateway=(env.GATEWAY_URL||"").replace(/\/$/,"");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_sessions (token_hash TEXT PRIMARY KEY, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
await sql.unsafe("ALTER TABLE jarvis_sessions ALTER COLUMN expires_at DROP NOT NULL");
await sql.unsafe("UPDATE jarvis_sessions SET expires_at=NULL WHERE expires_at>NOW()");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_login_limits (ip_hash TEXT PRIMARY KEY, failures INTEGER NOT NULL DEFAULT 0, window_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), blocked_until TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_provider_cooldowns (provider TEXT PRIMARY KEY, cooldown_until TIMESTAMPTZ NOT NULL, reason TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_claims (id BIGSERIAL PRIMARY KEY, task_id BIGINT UNIQUE, platform TEXT, title TEXT NOT NULL, source_url TEXT, claim_url TEXT, external_claim_id TEXT, payout_amount NUMERIC(20,8), payout_currency TEXT, payout_address TEXT, status TEXT NOT NULL DEFAULT 'claim_ready' CHECK(status IN ('claim_ready','submitted','accepted','payable','paid','rejected')), evidence JSONB NOT NULL DEFAULT '{}'::jsonb, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), submitted_at TIMESTAMPTZ, accepted_at TIMESTAMPTZ, paid_at TIMESTAMPTZ)");
await sql.unsafe("CREATE INDEX IF NOT EXISTS jarvis_claims_status_idx ON jarvis_claims(status,updated_at DESC)");
await sql.unsafe("ALTER TABLE jarvis_claims ALTER COLUMN payout_address SET DEFAULT 'bc1qag24fy59farlnn7npwt965x65ykkm2xjye66ag'");
await sql.unsafe("UPDATE jarvis_claims SET payout_address='bc1qag24fy59farlnn7npwt965x65ykkm2xjye66ag' WHERE payout_address IS NULL OR payout_address=''");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_wallet_routes (address TEXT PRIMARY KEY, label TEXT NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
await sql.unsafe("INSERT INTO jarvis_wallet_routes(address,label,is_primary) VALUES ('bc1qag24fy59farlnn7npwt965x65ykkm2xjye66ag','Owner wallet · primary',TRUE),('bc1q5ettmtf94lufc7yrz62fvf8sf43p35x4h0clkj','Owner wallet · secondary',FALSE) ON CONFLICT(address) DO UPDATE SET label=EXCLUDED.label,is_primary=EXCLUDED.is_primary");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_claim_verifications (id BIGSERIAL PRIMARY KEY, claim_id BIGINT NOT NULL REFERENCES jarvis_claims(id) ON DELETE CASCADE, verifier TEXT NOT NULL, verdict TEXT NOT NULL CHECK(verdict IN ('verified','rejected','inconclusive')), evidence_url TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(claim_id,verifier))");
await sql.unsafe("CREATE INDEX IF NOT EXISTS jarvis_claim_verifications_checked_idx ON jarvis_claim_verifications(claim_id,checked_at DESC)");
await sql.unsafe("CREATE TABLE IF NOT EXISTS jarvis_library_items (id BIGSERIAL PRIMARY KEY,title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('image','file','note')),mime_type TEXT,file_name TEXT,content_base64 TEXT,source_url TEXT,size_bytes BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())");
await sql.unsafe("CREATE INDEX IF NOT EXISTS jarvis_library_items_created_idx ON jarvis_library_items(created_at DESC)");

function json(data,status=200,headers={}){return new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","x-frame-options":"DENY",...headers}})}
async function hash(value){const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(value));return Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,"0")).join("")}
function cookie(req){const m=(req.headers.get("cookie")||"").match(/(?:^|;\s*)jarvis_session=([^;]+)/);return m?m[1]:""}
async function authenticated(req){const token=cookie(req);if(!token)return false;const h=await hash(token);const rows=await sql.unsafe("SELECT 1 FROM jarvis_sessions WHERE token_hash=$1 AND (expires_at IS NULL OR expires_at>NOW()) LIMIT 1",[h]);return rows.length>0}
async function gatewayCall(path,owner=false,body=null){if(!gateway)throw new Error("Gateway URL fehlt");const key=owner?env.OWNER_API_KEY:env.AGENT_API_KEY;if(!key)throw new Error(owner?"Owner API credential fehlt":"Agent API credential fehlt");const r=await fetch(gateway+path,{method:body?"POST":"GET",headers:{authorization:"Bearer "+key,...(body?{"content-type":"application/json"}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(30000)});const raw=await r.text();let data;try{data=JSON.parse(raw)}catch{data={error:raw.slice(0,500)}}if(!r.ok)throw new Error(data.error||"Gateway HTTP "+r.status);return data}
