 if(req.method==="GET"&&u.pathname==="/")return new Response(html,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","clear-site-data":"\"cache\"","content-security-policy":"default-src 'self' https: 'unsafe-inline'; connect-src 'self' https: http://*.railway.internal; img-src 'self' data: https:"}});
