   async function consultChatGPT(args){const repo=String(env.JARVIS_BRIDGE_REPOSITORY||"").trim(),token=String(env.JARVIS_BRIDGE_TOKEN||"").trim();if(!repo||!token)return {ok:false,error:"Private Bridge not configured: JARVIS_BRIDGE_REPOSITORY and JARVIS_BRIDGE_TOKEN are missing."};if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo))return {ok:false,error:"Bridge repository must be owner/repo."};const payload={from:"JARVIS",to:"ChatGPT",message_id:crypto.randomUUID(),type:String(args.type||"review"),subject:String(args.subject||"Expert review").slice(0,160),message:String(args.message||"").slice(0,20000),created_at:new Date().toISOString(),status:"open"};if(!payload.message)return {ok:false,error:"Message missing."};const r=await fetch("https://api.github.com/repos/"+repo+"/issues",{method:"POST",headers:{authorization:"Bearer "+token,accept:"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28","content-type":"application/json"},body:JSON.stringify({title:"[JARVIS -> ChatGPT] "+payload.subject,body:"\x60\x60\x60json\\n"+JSON.stringify(payload,null,2)+"\\n\x60\x60\x60"})});let d={};try{d=await r.json()}catch{}if(!r.ok)return {ok:false,error:"GitHub Bridge HTTP "+r.status+": "+String(d.message||"unknown error").slice(0,300)};return {ok:true,issue:d.number,url:d.html_url,message_id:payload.message_id,status:"open"};}
